SET LOCAL statement_timeout='60s'; SET LOCAL lock_timeout='5s';
-- First SQL inside the orchestrator's bounded transaction.
-- Metadata and digest-only row reads; all writes below are pg_temp only.
-- pg_get_functiondef/pg_get_expr qualify types according to search_path.
-- Pin introspection on both sides so an own-schema install cannot create drift.
SET LOCAL search_path = public,extensions;
CREATE TEMP TABLE k135_protected_schemas(oid oid PRIMARY KEY,name text) ON COMMIT DROP;
INSERT INTO pg_temp.k135_protected_schemas
 SELECT oid,nspname FROM pg_namespace WHERE nspname NOT LIKE 'pg\_%' ESCAPE '\' AND nspname<>'information_schema';

CREATE TEMP TABLE k135_protected_catalog(kind text,object_id oid,fingerprint text,PRIMARY KEY(kind,object_id)) ON COMMIT DROP;
-- Empty by default. The separately reviewed final-only replacement companion
-- may retire ten old own135 entry points; no PMB/Sales/Auth ACL is exempted.
CREATE TEMP TABLE k135_retired_own_api_plan(object_id oid PRIMARY KEY,expected_acl aclitem[]) ON COMMIT DROP;
CREATE TEMP TABLE k135_protected_functions(object_id oid PRIMARY KEY,non_acl_fingerprint text,original_acl aclitem[]) ON COMMIT DROP;
INSERT INTO pg_temp.k135_protected_functions
 SELECT p.oid,md5(concat_ws('|',pg_get_functiondef(p.oid),p.proowner::text,p.proconfig::text)),p.proacl
 FROM pg_proc p JOIN pg_temp.k135_protected_schemas n ON n.oid=p.pronamespace WHERE p.prokind='f';
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'function',p.oid,md5(concat_ws('|',pg_get_functiondef(p.oid),p.proowner::text,p.proacl::text,p.proconfig::text))
 FROM pg_proc p JOIN pg_temp.k135_protected_schemas n ON n.oid=p.pronamespace WHERE p.prokind='f';
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'relation',c.oid,md5(to_jsonb(c)::text) FROM pg_class c JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'sequence_definition',s.seqrelid,md5(to_jsonb(s)::text) FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'index',i.indexrelid,md5(to_jsonb(i)::text) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'constraint',c.oid,md5(to_jsonb(c)::text) FROM pg_constraint c JOIN pg_temp.k135_protected_schemas n ON n.oid=c.connamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'trigger',t.oid,md5(to_jsonb(t)::text) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'policy',p.oid,md5(to_jsonb(p)::text) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog SELECT 'namespace',n.oid,md5(to_jsonb(n)::text) FROM pg_namespace n JOIN pg_temp.k135_protected_schemas s ON s.oid=n.oid;
INSERT INTO pg_temp.k135_protected_catalog SELECT 'roles',r.oid,md5(to_jsonb(r)::text) FROM pg_roles r;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'type',t.oid,md5(to_jsonb(t)::text) FROM pg_type t JOIN pg_temp.k135_protected_schemas n ON n.oid=t.typnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'enum',e.oid,md5(to_jsonb(e)::text) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_temp.k135_protected_schemas n ON n.oid=t.typnamespace;
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'rule',r.oid,md5(to_jsonb(r)::text||pg_get_ruledef(r.oid,true)) FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace;
INSERT INTO pg_temp.k135_protected_catalog SELECT 'publication',p.oid,md5(to_jsonb(p)::text) FROM pg_publication p;
INSERT INTO pg_temp.k135_protected_catalog SELECT 'publication_relation',p.oid,md5(to_jsonb(p)::text) FROM pg_publication_rel p;
CREATE TEMP TABLE k135_publication_source_members(publication_id oid,source_schema text,source_name text,attributes int2vector,
 row_filter text,replica_identity "char",PRIMARY KEY(publication_id,source_schema,source_name)) ON COMMIT DROP;
INSERT INTO pg_temp.k135_publication_source_members
 SELECT p.prpubid,n.nspname,c.relname,p.prattrs,pg_get_expr(p.prqual,p.prrelid),c.relreplident
 FROM pg_publication_rel p JOIN pg_class c ON c.oid=p.prrelid JOIN pg_namespace n ON n.oid=c.relnamespace;
CREATE TEMP TABLE k135_own_namespace_map(source_schema text PRIMARY KEY,target_schema text UNIQUE) ON COMMIT DROP;
