 ('pdc_usage_private','karratha135_usage');
INSERT INTO pg_temp.k135_protected_catalog
 SELECT 'defaults',d.oid,md5(to_jsonb(d)::text) FROM pg_default_acl d WHERE d.defaclnamespace=0 OR d.defaclnamespace IN(SELECT oid FROM pg_temp.k135_protected_schemas);

CREATE TEMP TABLE k135_protected_columns(object_id oid,attribute_number integer,fingerprint text,PRIMARY KEY(object_id,attribute_number)) ON COMMIT DROP;
INSERT INTO pg_temp.k135_protected_columns
 SELECT a.attrelid,a.attnum,md5(to_jsonb(a)::text||coalesce(pg_get_expr(d.adbin,d.adrelid),''))
 FROM pg_attribute a JOIN pg_temp.k135_protected_catalog p ON p.kind='relation' AND p.object_id=a.attrelid
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped;
CREATE TEMP TABLE k135_protected_role_bindings(fingerprint text) ON COMMIT DROP;
INSERT INTO pg_temp.k135_protected_role_bindings
 SELECT md5(coalesce(string_agg(to_jsonb(m)::text,E'\n' ORDER BY m.roleid,m.member,m.grantor),'')) FROM pg_auth_members m;

CREATE TEMP TABLE k135_protected_data(object_id oid,schema_name text,table_name text,row_count bigint,row_hash text,where_clause text,PRIMARY KEY(object_id)) ON COMMIT DROP;
CREATE TEMP TABLE k135_clock_allowance(source_job jsonb,allocator_before jsonb) ON COMMIT DROP;
CREATE TEMP TABLE k135_concurrent_cron_allocator(before_state jsonb,after_state jsonb,
 captured_from timestamptz,captured_to timestamptz,protected_job_ids bigint[],
 first_runid bigint,last_runid bigint,requires_external_proof boolean NOT NULL DEFAULT false) ON COMMIT DROP;
DO $external_clock_metadata$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_sequence WHERE seqrelid='cron.runid_seq'::regclass AND seqincrement=1 AND seqcache=1 AND NOT seqcycle) THEN
  RAISE EXCEPTION 'Concurrent cron run allocator attributes differ';END IF;
 INSERT INTO pg_temp.k135_concurrent_cron_allocator(before_state,captured_from,protected_job_ids)
 SELECT jsonb_build_object('last_value',s.last_value,'log_cnt',s.log_cnt,'is_called',s.is_called),clock_timestamp(),
  ARRAY(SELECT jobid FROM cron.job ORDER BY jobid) FROM cron.runid_seq s;
END $external_clock_metadata$;
DO $clock_metadata$
BEGIN
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobname='k135-staging-workshop-clock-cascade') THEN
  RAISE EXCEPTION 'Fresh135 clock already exists; inspect it before install';
 END IF;
 IF (SELECT count(*) FROM cron.job WHERE jobname='staging-workshop-clock-cascade')<>1 THEN
  RAISE EXCEPTION 'Exact PMB clock reference missing or ambiguous';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_sequence WHERE seqrelid='cron.jobid_seq'::regclass AND seqincrement=1 AND seqcache=1 AND NOT seqcycle) THEN
  RAISE EXCEPTION 'Cron allocator attributes differ from reviewed single increment';
 END IF;
 INSERT INTO pg_temp.k135_clock_allowance SELECT to_jsonb(j),jsonb_build_object('last_value',s.last_value,'log_cnt',s.log_cnt,'is_called',s.is_called)
  FROM cron.job j CROSS JOIN cron.jobid_seq s WHERE j.jobname='staging-workshop-clock-cascade';
END $clock_metadata$;
DO $fingerprint$
DECLARE t record; filter text;row_expression text;
BEGIN
 IF EXISTS(SELECT 1 FROM storage.buckets WHERE id='karratha135-qc-evidence-staging') THEN
  RAISE EXCEPTION 'Fresh135 bucket already exists; compare/review it explicitly before installing companion';
 END IF;
 FOR t IN SELECT c.oid,n.name,c.relname,c.relkind FROM pg_class c JOIN pg_temp.k135_protected_schemas n ON n.oid=c.relnamespace
  WHERE c.relkind IN('r','p','S') ORDER BY n.name,c.relname LOOP
  filter:=CASE
   WHEN t.name='storage' AND t.relname='buckets' THEN ' WHERE id<>''karratha135-qc-evidence-staging'''
   WHEN t.name='storage' AND t.relname='objects' THEN ' WHERE bucket_id<>''karratha135-qc-evidence-staging'''
   WHEN t.name='cron' AND t.relname='job' THEN ' WHERE jobname IS DISTINCT FROM ''k135-staging-workshop-clock-cascade'''
   ELSE '' END;
  row_expression:=CASE WHEN t.relkind='S' THEN 'jsonb_build_object(''last_value'',x.last_value,''log_cnt'',x.log_cnt,''is_called'',x.is_called)' ELSE 'to_jsonb(x)' END;
  EXECUTE format('INSERT INTO pg_temp.k135_protected_data SELECT %s,%L,%L,count(*),md5(coalesce(string_agg(h,'''' ORDER BY h),'''')),%L FROM (SELECT md5(%s::text) h FROM %I.%I x%s) q',
   t.oid,t.name,t.relname,filter,row_expression,t.name,t.relname,filter);
 END LOOP;
END $fingerprint$;

DO $legacy_empty_guard$ BEGIN IF EXISTS(SELECT 1 FROM karratha_pdc.vehicles) OR EXISTS(SELECT 1 FROM karratha_pdc.operations) OR EXISTS(SELECT 1 FROM karratha_pdc.jobcards) OR EXISTS(SELECT 1 FROM karratha_pdc.bookings) OR EXISTS(SELECT 1 FROM karratha_pdc.import_previews) OR EXISTS(SELECT 1 FROM karratha_pdc.import_receipts) THEN RAISE EXCEPTION 'Existing Karratha operational records require reviewed migration before replacement'; END IF; END $legacy_empty_guard$;
-- Mechanical candidate only. No PMB business rows are copied. No persistent apply until exceptions are reviewed.
DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd') OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL THEN RAISE EXCEPTION 'Exact staging required';END IF; IF to_regnamespace('karratha135_pdc') IS NOT NULL THEN RAISE EXCEPTION 'Native Karratha namespace already exists';END IF;END $guard$;
SET LOCAL check_function_bodies = false;
