-- Explicit own-centre Auth/session boundary. Shared Auth is read-only.
CREATE TABLE karratha135_pdc.engine_release_135(
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),ready boolean NOT NULL DEFAULT false,
 engine_version text NOT NULL,proof_sha256 text CHECK(proof_sha256 IS NULL OR proof_sha256~'^[a-f0-9]{64}$'),
 approved_at timestamptz,approved_by uuid,
 CHECK(NOT ready OR (proof_sha256 IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL))
);
INSERT INTO karratha135_pdc.engine_release_135(singleton,ready,engine_version) VALUES(true,false,'pmb-native135-candidate-v1');
ALTER TABLE karratha135_pdc.engine_release_135 ENABLE ROW LEVEL SECURITY;
ALTER TABLE karratha135_pdc.engine_release_135 FORCE ROW LEVEL SECURITY;
REVOKE ALL ON karratha135_pdc.engine_release_135 FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION karratha135_pdc.verified_auth_session_135() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $guard$
DECLARE v_uid uuid:=auth.uid();v_session text:=auth.jwt()->>'session_id';
BEGIN
 IF v_uid IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated'
  OR coalesce(auth.jwt()->>'is_anonymous','false')='true' THEN
  RAISE EXCEPTION 'Karratha sign-in required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=v_uid
  AND lower(u.email)=lower(coalesce(auth.jwt()->>'email',''))
  AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)
  AND (u.banned_until IS NULL OR u.banned_until<=now())) THEN
  RAISE EXCEPTION 'Karratha sign-in is no longer valid' USING ERRCODE='42501';END IF;
 IF v_session IS NULL OR v_session !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  THEN RAISE EXCEPTION 'Karratha session is no longer active' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.sessions s WHERE s.id=v_session::uuid
  AND s.user_id=v_uid AND (s.not_after IS NULL OR s.not_after>now())) THEN
  RAISE EXCEPTION 'Karratha session is no longer active' USING ERRCODE='42501';END IF;
 RETURN v_uid;
END $guard$;
CREATE FUNCTION karratha135_pdc.require_active_session_135() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $guard$
DECLARE v_uid uuid:=karratha135_pdc.verified_auth_session_135();
BEGIN
 IF (SELECT count(*) FROM karratha135_pdc.pdc_user_roles r
  WHERE r.auth_user_id=v_uid AND r.email=lower(coalesce(auth.jwt()->>'email',''))
  AND r.active AND r.account_status='approved' AND r.role IS NOT NULL)<>1 THEN
  RAISE EXCEPTION 'Karratha access is not approved' USING ERRCODE='42501';END IF;
 IF NOT coalesce((SELECT ready FROM karratha135_pdc.engine_release_135 WHERE singleton),false) THEN
  RAISE EXCEPTION 'Karratha engine is not released' USING ERRCODE='42501';END IF;
 RETURN v_uid;
END $guard$;
CREATE FUNCTION karratha135_pdc.native_engine_context_135() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $guard$
DECLARE v_uid uuid:=karratha135_pdc.verified_auth_session_135();v_role karratha135_pdc.pdc_user_roles;
BEGIN
 SELECT r.* INTO v_role FROM karratha135_pdc.pdc_user_roles r WHERE r.auth_user_id=v_uid
  AND r.email=lower(coalesce(auth.jwt()->>'email',''));
 RETURN jsonb_build_object('centre','KARRATHA','store_code','135','user_id',v_uid,
  'role',v_role.role,'account_status',v_role.account_status,'active',v_role.active,
  'display_name',coalesce(v_role.display_name,v_role.full_name),'membership_id',v_role.id,
  'membership_version',md5(coalesce(v_role.updated_at::text,'')||coalesce(v_role.role::text,'')||coalesce(v_role.active::text,'')||coalesce(v_role.account_status::text,'')),
  'engine_version',(SELECT engine_version FROM karratha135_pdc.engine_release_135 WHERE singleton),
  'ready',coalesce((SELECT ready FROM karratha135_pdc.engine_release_135 WHERE singleton),false));
END $guard$;
CREATE FUNCTION karratha135_pdc.request_department_access_135(p_display_name text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $guard$
DECLARE v_uid uuid:=karratha135_pdc.verified_auth_session_135();v_email text:=lower(auth.jwt()->>'email');
BEGIN
 IF length(coalesce(p_display_name,''))>200 THEN RAISE EXCEPTION 'Display name too long' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('k135:request-department-access:'||v_uid::text,0));
 IF EXISTS(SELECT 1 FROM karratha135_pdc.pdc_user_roles r WHERE r.email=v_email AND r.auth_user_id IS DISTINCT FROM v_uid) THEN
  RAISE EXCEPTION 'Karratha identity requires administrator review' USING ERRCODE='42501';END IF;
 INSERT INTO karratha135_pdc.pdc_user_roles(email,display_name,full_name,auth_user_id,active,account_status,registered_at)
 SELECT v_email,nullif(btrim(p_display_name),''),nullif(btrim(p_display_name),''),v_uid,false,'pending',now()
 WHERE NOT EXISTS(SELECT 1 FROM karratha135_pdc.pdc_user_roles r WHERE r.auth_user_id=v_uid OR r.email=v_email);
 RETURN karratha135_pdc.native_engine_context_135();
END $guard$;
CREATE FUNCTION karratha135_pdc.owned_selected_vehicle_135(p_vehicle_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $owned$
 SELECT EXISTS(
  SELECT 1 FROM karratha135_pdc.vehicles v
  JOIN karratha135_pdc.pdc_pilbara_service_operations o ON o.vehicle_id=v.id
  JOIN karratha135_pdc.pdc_pilbara_service_import_rows r ON r.evidence_id=o.raw_evidence_id
  WHERE v.id=p_vehicle_id AND v.deleted_at IS NULL AND v.lifecycle_state IN('active','rft','completed')
   AND o.department='135' AND r.normalized_payload->>'department'='135'
 );
$owned$;
REVOKE ALL ON FUNCTION karratha135_pdc.owned_selected_vehicle_135(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.k135_get_native_engine_context() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER
SET search_path=pg_catalog AS $guard$ SELECT karratha135_pdc.native_engine_context_135() $guard$;
