nb:=''[]'';\n state_code text; detail text; after_row jsonb; unavailable_date date; technician uuid; bus_rule jsonb;\nBEGIN\n IF NOT coalesce((SELECT ready FROM karratha135_pdc.engine_release_135 WHERE singleton),false) THEN RETURN jsonb_build_object(''ok'',true,''disabled'',true,''engine_ready'',false,''code'',''k135_engine_not_ready'',''moved_count'',0);END IF;\n IF NOT EXISTS(SELECT 1 FROM karratha135_pdc.pdc_staging_environment_sentinel WHERE singleton AND project_ref=''cdsmnqxtyyoeoznmbidd'')\n  OR to_regclass(''public.pdc_production_environment_sentinel'') IS NOT NULL THEN RAISE EXCEPTION ''STAGING only''; END IF;\n IF NOT karratha135_pdc.workshop_future_only_schedule_enabled() THEN RETURN jsonb_build_object(''ok'',true,''disabled'',true,''moved_count'',0); END IF;\n IF NOT pg_try_advisory_xact_lock(hashtextextended(''k135:workshop-clock-cascade-20260911'',0)) THEN RETURN jsonb_build_object(''ok'',true,''busy'',true,''moved_count'',0); END IF;\n -- Match the existing planner''s mutation gate, then lock a stable snapshot.\n PERFORM pg_advisory_xact_lock(hashtextextended(''k135:pdc:workshop:top-level-mutation'',0));\n PERFORM 1 FROM karratha135_pdc.workshop_bookings WHERE deleted_at IS NULL AND status IN(''planned'',''queued'',''started'',''stoppage'') ORDER BY id FOR UPDATE;\n PERFORM 1 FROM karratha135_pdc.workshop_booking_assignments WHERE released_at IS NULL ORDER BY id FOR UPDATE;\n PERFORM 1 FROM karratha135_pdc.workshop_admin_blocks WHERE deleted_at IS NULL ORDER BY id FOR SHARE;\n floor_at:=karratha135_pdc.workshop_clock_next_minute(p_now);\n DROP TABLE IF EXISTS pg_temp.k135_clock_linked_plan;\n CREATE TEMP TABLE k135_clock_linked_plan ON COMMIT DROP AS\n SELECT row_number() OVER(ORDER BY b.scheduled_start_at,b.id) ordinal,b.id,b.vehicle_id,b.bay_id,b.stage_id,s.code stage,\n  CASE WHEN s.code=''BUS_4X4'' AND karratha135_bus.active_vehicle(b.vehicle_id) THEN b.bay_id END calendar_bay_id,\n  b.status::text status,b.actual_start_at,b.scheduled_start_at original_start,b.scheduled_end_at original_end,\n  b.scheduled_start_at final_start,b.scheduled_end_at final_end,b.default_duration_minutes duration,b.version,\n  karratha135_pdc.workshop_booking_effective_end_at(b.id) effective_end,w.accounted_through,\n  coalesce((SELECT array_agg(DISTINCT a.technician_id) FROM karratha135_pdc.workshop_booking_assignments a WHERE a.booking_id=b.id AND a.released_at IS NULL),''{}''::uuid[]) technicians,\n  b.id::text component_id,0::integer delay,false changed,false seed,\n  (y.is_active AND s.active AND s.planner_enabled) enabled,to_jsonb(b) before_row\n FROM karratha135_pdc.workshop_bookings b JOIN karratha135_pdc.workshop_stages s ON s.id=b.stage_id\n LEFT JOIN karratha135_pdc.workshop_bays y ON y.id=b.bay_id LEFT JOIN karratha135_pdc.workshop_clock_watermarks w ON w.booking_id=b.id\n WHERE b.deleted_at IS NULL AND b.status IN(''planned'',''queued'',''started'',''stoppage'');\n CREATE UNIQUE INDEX ON k135_clock_linked_plan(id);\n CREATE INDEX ON k135_clock_linked_plan(component_id);\n -- Keep each connected resource group atomic; unrelated bays can still advance.\n LOOP\n  UPDATE pg_temp.k135_clock_linked_plan a SET component_id=q.leader FROM\n   (SELECT a1.id,min(b1.component_id) leader FROM pg_temp.k135_clock_linked_plan a1 JOIN pg_temp.k135_clock_linked_plan b1\n    ON a1.bay_id=b1.bay_id OR a1.vehicle_id=b1.vehicle_id OR a1.technicians && b1.technicians GROUP BY a1.id) q\n   WHERE a.id=q.id AND q.leader<a.component_id;\n  GET DIAGNOSTICS count_changed=ROW_COUNT; EXIT WHEN count_changed=0;\n END LOOP;\n FOR component IN SELECT DISTINCT p.component_id FROM pg_temp.k135_clock_linked_plan p\n  WHERE p.enabled AND ((p.status=''planned'' AND p.actual_start_at IS NULL AND p.original_start<p_now)\n   OR (p.status IN(''started'',''stoppage'') AND greatest(p.effective_end,karratha135_bus.clock_next_minute(p_now,p.calendar_bay_id))>p.original_end)) ORDER BY p.component_id\n LOOP\n  BEGIN\n   marks:=''[]''; component_moved:=0;\n   FOR bay IN SELECT DISTINCT bay_id FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id AND bay_id IS NOT NULL ORDER BY bay_id LOOP\n    PERFORM karratha135_pdc.workshop_lock_resources(bay.bay_id,NULL);\n    SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''status'',status,''start'',original_start,''end'',original_end,''effective_end'',effective_end,\n     ''duration'',duration,''actual_start'',actual_start_at,''accounted_through'',accounted_through,''calendar_bay_id'',calendar_bay_id)),''[]'') INTO rows FROM pg_temp.k135_clock_linked_plan WHERE bay_id=bay.bay_id;\n    SELECT coalesce(jsonb_agg(jsonb_build_object(''start'',scheduled_start_at,''end'',scheduled_end_at)),''[]'') INTO blocks\n     FROM karratha135_pdc.workshop_admin_blocks WHERE bay_id=bay.bay_id AND deleted_at IS NULL AND scheduled_end_at>=p_now;\n    plan:=karratha135_pdc.workshop_clock_plan(rows,blocks,p_now);\n    marks:=marks||(plan->''watermarks'');\n    FOR movement IN SELECT x FROM jsonb_array_elements(plan->''moves'') x LOOP\n     UPDATE pg_temp.k135_clock_linked_plan SET final_start=(movement->>''to'')::timestamptz,final_end=(movement->>''end'')::timestamptz,seed=true\n      WHERE id=(movement->>''id'')::uuid;\n    END LOOP;\n   END LOOP;\n   -- Walk the original chronological order. Resource edges only point forward.\n   FOR item IN SELECT * FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id ORDER BY ordinal LOOP\n    floor_at:=karratha135_bus.clock_next_minute(p_now,item.calendar_bay_id);\n    IF item.status IN(''started'',''stoppage'') OR item.actual_start_at IS NOT NULL THEN\n     UPDATE pg_temp.k135_clock_linked_plan SET final_end=greatest(item.original_end,item.effective_end,floor_at),\n      delay=greatest(0,karratha135_bus.clock_minutes_between(greatest(item.original_end,coalesce(item.accounted_through,item.original_end)),greatest(item.original_end,item.effective_end,floor_at),item.calendar_bay_id))\n      WHERE id=item.id;\n     CONTINUE;\n    END IF;\n    proposed:=item.final_start;\n    delay:=greatest(0,karratha135_bus.clock_minutes_between(item.original_start,proposed,item.calendar_bay_id));\n    FOR predecessor IN SELECT * FROM pg_temp.k135_clock_linked_plan x WHERE x.component_id=component.component_id AND x.ordinal<item.ordinal\n     AND (x.bay_id=item.bay_id OR x.vehicle_id=item.vehicle_id OR x.technicians && item.technicians)\n     AND (x.changed OR x.delay>0) ORDER BY x.ordinal LOOP\n     delay:=greatest(delay,predecessor.delay);\n     proposed:=greatest(proposed,predecessor.final_end+CASE WHEN predecessor.vehicle_id=item.vehicle_id THEN interval ''1 hour'' ELSE interval ''0 minutes'' END);\n    END LOOP;\n    proposed:=greatest(proposed,karratha135_bus.clock_add_minutes(item.original_start,delay,item.calendar_bay_id));\n    IF NOT item.seed AND proposed<=item.original_start THEN CONTINUE; END IF;\n    IF item.status<>''planned'' OR item.bay_id IS NULL OR NOT item.enabled THEN\n     RAISE EXCEPTION ''A dependent booking cannot move automatically: %'',item.id USING errcode=''22023''; END IF;\n    -- Preserve unchanged predecessors too, without reordering a vehicle''s jobs.\n    SELECT max(x.final_end+CASE WHEN x.vehicle_id=item.vehicle_id THEN interval ''1 hour'' ELSE interval ''0 minutes'' END) INTO obstacle\n     FROM pg_temp.k135_clock_linked_plan x WHERE x.component_id=component.component_id AND x.ordinal<item.ordinal\n      AND (x.bay_id=item.bay_id OR x.vehicle_id=item.vehicle_id OR x.technicians && item.technicians);\n    proposed:=greatest(proposed,obstacle,floor_at); loop_count:=0;\n    LOOP\n     loop_count:=loop_count+1; IF loop_count>1000 THEN RAISE EXCEPTION ''Clock obstacle limit'' USING errcode=''22023''; END IF;\n     proposed:=karratha135_bus.clock_next_minute(proposed,item.calendar_bay_id);\n     finish:=karratha135_bus.clock_add_minutes(proposed,item.duration,item.calendar_bay_id);\n     SELECT max(scheduled_end_at) INTO obstacle FROM karratha135_pdc.workshop_admin_blocks\n      WHERE bay_id=item.bay_id AND deleted_at IS NULL AND scheduled_start_at<finish AND scheduled_end_at>proposed;\n     -- Started, stopped and queued bookings are fixed obstacles in either direction.\n     SELECT greatest(obstacle,max(greatest(x.original_end,x.effective_end,CASE WHEN x.status IN(''started'',''stoppage'') THEN karratha135_bus.clock_next_minute(p_now,x.calendar_bay_id) END))) INTO obstacle\n      FROM pg_temp.k135_clock_linked_plan x WHERE x.id<>item.id AND (x.status IN(''started'',''stoppage'',''queued'') OR x.actual_start_at IS NOT NULL)\n       AND (x.bay_id=item.bay_id OR x.vehicle_id=item.vehicle_id OR x.technicians && item.technicians)\n       AND x.original_start<finish AND greatest(x.original_end,x.effective_end,CASE WHEN x.status IN(''started'',''stoppage'') THEN karratha135_bus.clock_next_minute(p_now,x.calendar_bay_id) END)>proposed;\n     SELECT max(d::date) INTO unavailable_date FROM generate_series((proposed AT TIME ZONE ''Australia/Perth'')::date::timestamp,\n      ((finish-interval ''1 minute'') AT TIME ZONE ''Australia/Perth'')::date::timestamp,interval ''1 day'') d WHERE karratha135_pdc.pdc_sublet_away_on_date(item.vehicle_id,d::date);\n     IF unavailable_date IS NOT NULL THEN obstacle:=greatest(obstacle,(unavailable_date+1)::timestamp AT TIME ZONE ''Australia/Perth''); END IF;\n     FOREACH technician IN ARRAY item.technicians LOOP\n      unavailable_date:=karratha135_pdc.workshop_technician_leave_date(technician,proposed,finish);\n      IF unavailable_date IS NOT NULL THEN obstacle:=greatest(obstacle,(unavailable_date+1)::timestamp AT TIME ZONE ''Australia/Perth''); END IF;\n     END LOOP;\n     EXIT WHEN obstacle IS NULL; proposed:=greatest(proposed+interval ''1 minute'',obstacle);\n    END LOOP;\n    IF item.calendar_bay_id IS NOT NULL THEN\n     bus_rule:=karratha135_bus.booking_rule(item.vehicle_id,item.bay_id,item.id);\n     IF bus_rule->>''ok'' IS DISTINCT FROM ''true'' THEN\n      RAISE EXCEPTION ''Bus workflow: %'',bus_rule USING errcode=''23514'';\n     END IF;\n    END IF;\n    UPDATE pg_temp.k135_clock_linked_plan SET final_start=proposed,final_end=finish,\n     delay=greatest(delay,karratha135_bus.clock_minutes_between(item.original_start,proposed,item.calendar_bay_id)),\n     changed=(proposed IS DISTINCT FROM item.original_start OR finish IS DISTINCT FROM item.original_end) WHERE id=item.id;\n   END LOOP;\n   IF EXISTS(SELECT 1 FROM pg_temp.k135_clock_linked_plan a JOIN pg_temp.k135_clock_linked_plan b\n    ON a.component_id=b.component_id AND a.ordinal<b.ordinal\n    WHERE a.component_id=component.component_id AND (a.changed OR b.changed)\n     AND (a.bay_id=b.bay_id OR a.vehicle_id=b.vehicle_id OR a.technicians && b.technicians)\n     AND a.final_end+CASE WHEN a.vehicle_id=b.vehicle_id THEN interval ''1 hour'' ELSE interval ''0 minutes'' END>b.final_start) THEN\n    RAISE EXCEPTION ''A dependent current or queued job prevents preserving workshop order'' USING errcode=''22023'';\n   END IF;\n   IF p_apply THEN\n    FOR item IN SELECT * FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id AND changed ORDER BY ordinal DESC LOOP\n     UPDATE karratha135_pdc.workshop_bookings SET scheduled_start_at=item.final_start,scheduled_end_at=item.final_end,version=version+1,\n      updated_at=clock_timestamp(),updated_by=coalesce(auth.uid(),updated_by) WHERE id=item.id AND version=item.version AND status=''planned'' AND actual_start_at IS NULL AND deleted_at IS NULL;\n     IF NOT FOUND THEN RAISE EXCEPTION ''Clock booking changed'' USING errcode=''40001''; END IF;\n     SELECT to_jsonb(b) INTO after_row FROM karratha135_pdc.workshop_bookings b WHERE id=item.id;\n     -- A trigger must not silently alter the accepted plan or its shift basis.\n     IF (after_row->>''scheduled_start_at'')::timestamptz IS DISTINCT FROM item.final_start\n      OR (after_row->>''scheduled_end_at'')::timestamptz IS DISTINCT FROM item.final_end\n      OR (after_row->>''default_duration_minutes'')::integer IS DISTINCT FROM item.duration\n      OR (CASE WHEN item.calendar_bay_id IS NOT NULL\n       THEN (after_row->>''bus_calendar_version'')::integer IS DISTINCT FROM 1\n         OR coalesce((item.before_row->>''bus_calendar_version'')::integer,1)<>1\n       ELSE after_row->''bus_calendar_version'' IS DISTINCT FROM item.before_row->''bus_calendar_version'' END)\n     THEN RAISE EXCEPTION ''Clock persisted calendar differs from planned calendar'' USING errcode=''23514''; END IF;\n     UPDATE karratha135_pdc.workshop_booking_assignments SET scheduled_start_at=item.final_start,scheduled_end_at=item.final_end,updated_at=clock_timestamp() WHERE booking_id=item.id AND released_at IS NULL;\n     IF EXISTS(SELECT 1 FROM karratha135_pdc.workshop_booking_assignments a WHERE a.booking_id=item.id AND a.released_at IS NULL\n      AND (a.scheduled_start_at IS DISTINCT FROM item.final_start OR a.scheduled_end_at IS DISTINCT FROM item.final_end))\n     THEN RAISE EXCEPTION ''Clock assignment calendar differs from booking'' USING errcode=''23514''; END IF;\n     IF after_row-ARRAY[''scheduled_start_at'',''scheduled_end_at'',''version'',''updated_at'',''updated_by'',''eta_at_booking'',''eta_risk_status'',''eta_risk_detected_at'',''bus_calendar_version'']\n       IS DISTINCT FROM item.before_row-ARRAY[''scheduled_start_at'',''scheduled_end_at'',''version'',''updated_at'',''updated_by'',''eta_at_booking'',''eta_risk_status'',''eta_risk_detected_at'',''bus_calendar_version''] THEN\n      RAISE EXCEPTION ''Clock changed protected booking fields'' USING errcode=''23514''; END IF;\n     INSERT INTO karratha135_pdc.workshop_clock_history(booking_id,bay_id,clock_at,before_data,after_data) VALUES(item.id,item.bay_id,p_now,item.before_row,after_row);\n     component_moved:=component_moved+1;\n    END LOOP;\n    FOR watermark IN SELECT x FROM jsonb_array_elements(marks) x LOOP\n     INSERT INTO karratha135_pdc.workshop_clock_watermarks(booking_id,accounted_through) VALUES((watermark->>''id'')::uuid,(watermark->>''through'')::timestamptz)\n     ON CONFLICT(booking_id) DO UPDATE SET accounted_through=greatest(karratha135_pdc.workshop_clock_watermarks.accounted_through,excluded.accounted_through),updated_at=clock_timestamp();\n    END LOOP;\n    INSERT INTO karratha135_pdc.workshop_clock_status(bay_id,last_checked_at,last_success_at,moved_count)\n     SELECT bay_id,p_now,p_now,count(*) FILTER(WHERE changed)::integer FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id AND bay_id IS NOT NULL GROUP BY bay_id\n     ON CONFLICT(bay_id) DO UPDATE SET last_checked_at=excluded.last_checked_at,last_success_at=excluded.last_success_at,error_code=NULL,error_detail=NULL,moved_count=excluded.moved_count;\n   END IF;\n   SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''bay_id'',bay_id,''from'',original_start,''to'',final_start,''end'',final_end,''duration'',duration) ORDER BY ordinal),''[]'') INTO plan\n    FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id AND changed;\n   moved:=moved+component_moved; plans:=plans||jsonb_build_array(jsonb_build_object(''component'',component.component_id,''moves'',plan));\n  EXCEPTION WHEN SQLSTATE ''22023'' OR SQLSTATE ''23514'' OR SQLSTATE ''23P01'' OR SQLSTATE ''40001'' OR lock_not_available THEN\n   GET STACKED DIAGNOSTICS state_code=RETURNED_SQLSTATE,detail=MESSAGE_TEXT;\n   issues:=issues||jsonb_build_array(jsonb_build_object(''component'',component.component_id,''code'',state_code,''detail'',detail));\n   IF p_apply THEN\n    INSERT INTO karratha135_pdc.workshop_clock_status(bay_id,last_checked_at,error_code,error_detail)\n     SELECT DISTINCT bay_id,p_now,state_code,detail FROM pg_temp.k135_clock_linked_plan WHERE component_id=component.component_id AND bay_id IS NOT NULL\n     ON CONFLICT(bay_id) DO UPDATE SET last_checked_at=excluded.last_checked_at,error_code=excluded.error_code,error_detail=excluded.error_detail,moved_count=0;\n   END IF;\n  END