CREATE VIEW "karratha135_pdc"."pdc_effective_operation_lines" AS  WITH source_rows AS (
         SELECT ol.operation_line_id::text AS operation_line_identifier,
            ol.operation_line_id,
            ol.vehicle_id,
            COALESCE(a.job_card_number, ol.job_card_number) AS job_card_number,
            COALESCE(a.operation_code, ol.operation_no) AS operation_code,
            COALESCE(pdc_auditor_work_key_for_stage(a.stage_code), ol.work_key) AS work_key,
            COALESCE(a.description, ol.description) AS description,
            COALESCE(a.estimated_hours, ol.estimated_hours) AS estimated_hours,
            COALESCE(a.display_order, ol.source_row_no) AS display_order,
            COALESCE(a.active, true) AS active,
            COALESCE(a.manual_assignment_locked, false) AS manual_assignment_locked,
            a.adjustment_id,
            a.correction_origin
           FROM pdc_authenticated_email_operation_lines ol
             LEFT JOIN vehicle_workshop_line_adjustments a ON a.vehicle_id = ol.vehicle_id AND a.line_key = ('source:'::text || ol.operation_line_id::text) AND a.correction_origin IS DISTINCT FROM 'ai_auditor_rolled_back'::text
        ), added_rows AS (
         SELECT a.adjustment_id::text AS adjustment_id,
            a.source_operation_line_id,
            a.vehicle_id,
            a.job_card_number,
            a.operation_code,
            pdc_auditor_work_key_for_stage(a.stage_code) AS pdc_auditor_work_key_for_stage,
            a.description,
            a.estimated_hours,
            a.display_order,
            a.active,
            a.manual_assignment_locked,
            a.adjustment_id,
            a.correction_origin
           FROM vehicle_workshop_line_adjustments a
          WHERE a.correction_origin = 'ai_auditor'::text AND a.source_operation_line_id IS NULL AND a.active
        )
 SELECT source_rows.operation_line_identifier,
    source_rows.operation_line_id,
    source_rows.vehicle_id,
    source_rows.job_card_number,
    source_rows.operation_code,
    source_rows.work_key,
    source_rows.description,
    source_rows.estimated_hours,
    source_rows.display_order,
    source_rows.active,
    source_rows.manual_assignment_locked,
    source_rows.adjustment_id,
    source_rows.correction_origin
   FROM source_rows
UNION ALL
 SELECT added_rows.adjustment_id AS operation_line_identifier,
    added_rows.source_operation_line_id AS operation_line_id,
    added_rows.vehicle_id,
    added_rows.job_card_number,
    added_rows.operation_code,
    added_rows.pdc_auditor_work_key_for_stage AS work_key,
    added_rows.description,
    added_rows.estimated_hours,
    added_rows.display_order,
    added_rows.active,
    added_rows.manual_assignment_locked,
    added_rows.adjustment_id_1 AS adjustment_id,
    added_rows.correction_origin
   FROM added_rows added_rows(adjustment_id, source_operation_line_id, vehicle_id, job_card_number, operation_code, pdc_auditor_work_key_for_stage, description, estimated_hours, display_order, active, manual_assignment_locked, adjustment_id_1, correction_origin);
