INSERT INTO karratha135_pdc.workshop_technicians(id,name,role_type,active,can_fit_stages,leave_calendar,version,created_at,updated_at)
SELECT t.id,t.name,'technician',t.active,ARRAY(SELECT x FROM unnest(t.stage_codes) x WHERE x<>'BUS_4X4'),
 coalesce((SELECT jsonb_agg(jsonb_build_object('date',d::text)) FROM unnest(t.leave_dates) d),'[]'::jsonb),
 t.version,t.created_at,t.updated_at FROM karratha_pdc.technicians t;

INSERT INTO karratha135_pdc.workshop_bays(id,stage_id,bay_number,code,display_name,is_active,is_sublet_row,default_technician_id,version,efficiency_percent)
SELECT coalesce(o.id,gen_random_uuid()),s.id,1,'TINT-BAY-01','Tint Bay 01',coalesce(o.active,true),false,o.default_technician_id,coalesce(o.version,1),coalesce(o.efficiency_percent,100)
FROM karratha135_pdc.workshop_stages s LEFT JOIN karratha_pdc.bays o ON o.code='TINT-BAY-01' WHERE s.code='TINT';

