-- Candidate only. Two shared Navision relations are SELECT-only leaves.
-- Source UUIDs identify shared evidence. They never become operational vehicle IDs.
CREATE TABLE karratha135_pdc.shared_navision_projection_state_135(
 shared_record_id uuid PRIMARY KEY,
 shared_version integer NOT NULL,
 shared_updated_at timestamptz NOT NULL,
 refreshed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE karratha135_pdc.shared_navision_projection_state_135 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON karratha135_pdc.shared_navision_projection_state_135 FROM PUBLIC,anon,authenticated;

CREATE FUNCTION karratha135_pdc.refresh_shared_navision_135(p_rows jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,karratha135_pdc,extensions
SET lock_timeout='5s'
SET statement_timeout='60s'
AS $function$
DECLARE
 actor uuid;
 stocks text[];
 src public.navision_backend_records%rowtype;
 own karratha135_pdc.navision_backend_records%rowtype;
 state karratha135_pdc.shared_navision_projection_state_135%rowtype;
 own_link uuid;
 matches integer;
 copied integer:=0;
BEGIN
 actor:=karratha135_pdc.require_active_session_135();
 IF p_rows IS NOT NULL THEN
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array'
   OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 1000000
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) x
      WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
       OR coalesce(x->>'department',x->'raw_row'->>'Dept','')<>'135'
       OR (x ? 'department' AND x->'raw_row' ? 'Dept'
        AND x->>'department' IS DISTINCT FROM x->'raw_row'->>'Dept'))
  THEN RAISE EXCEPTION 'invalid_department135_source' USING ERRCODE='22023'; END IF;
  SELECT array_agg(DISTINCT btrim(x->>'stock_number')) INTO stocks
   FROM jsonb_array_elements(p_rows) x
   WHERE karratha135_pdc.is_real_vehicle_stock_number(x->>'stock_number');
 ELSE
  -- A read refresh can only touch source identities already belonging to this centre.
  SELECT array_agg(DISTINCT stock) INTO stocks FROM(
    SELECT btrim(coalesce(normalized_data->>'batch',normalized_data->>'stock','')) stock
     FROM karratha135_pdc.navision_backend_records
    UNION SELECT btrim(v.stock_number) FROM karratha135_pdc.vehicles v
     WHERE v.deleted_at IS NULL AND EXISTS(
      SELECT 1 FROM karratha135_pdc.pdc_pilbara_service_operations o
       WHERE o.vehicle_id=v.id AND o.department='135')
   ) q WHERE karratha135_pdc.is_real_vehicle_stock_number(stock);
 END IF;
 IF coalesce(cardinality(stocks),0)=0 THEN
  RETURN jsonb_build_object('ok',true,'refreshed',0);
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('k135:shared-navision-projection',0));
 FOR src IN
  SELECT s.* FROM public.navision_backend_records s
  WHERE s.source_system='microsoft_navision'
   AND (btrim(coalesce(s.normalized_data->>'batch',s.normalized_data->>'stock',''))=ANY(stocks)
     OR EXISTS(SELECT 1 FROM karratha135_pdc.shared_navision_projection_state_135 t
       WHERE t.shared_record_id=s.id))
  ORDER BY s.id
 LOOP
  SELECT * INTO state FROM karratha135_pdc.shared_navision_projection_state_135
   WHERE shared_record_id=src.id;
  IF FOUND AND state.shared_version=src.version
   AND state.shared_updated_at=src.updated_at THEN CONTINUE; END IF;

  -- Preserve exact import evidence in an own table; no shared triggers are installed here.
  INSERT INTO karratha135_pdc.navision_import_batches(
   id,idempotency_key,request_hash,source_name,source_timestamp,source_hash,preview_hash,
   base_revision,result_revision,status,total_rows,new_count,changed_count,unchanged_count,
   missing_count,invalid_count,conflict_count,receipt,actor_id,actor_email,applied_at,
   rolled_back_at,rolled_back_by,source_system,dealer_code)
  SELECT b.id,b.idempotency_key,b.request_hash,b.source_name,b.source_timestamp,b.source_hash,
   b.preview_hash,b.base_revision,b.result_revision,b.status,b.total_rows,b.new_count,b.changed_count,
   b.unchanged_count,b.missing_count,b.invalid_count,b.conflict_count,
   jsonb_build_object('contract','shared_navision_source_evidence_135','shared_batch_id',b.id,
     'source_hash',b.source_hash,'selected_record_projection',true),b.actor_id,
   b.actor_email,b.applied_at,b.rolled_back_at,b.rolled_back_by,b.source_system,b.dealer_code
  FROM public.navision_import_batches b
  WHERE b.id=ANY(ARRAY[src.first_seen_batch_id,src.last_seen_batch_id,src.missing_since_batch_id])
  ON CONFLICT(id) DO NOTHING;

  SELECT * INTO own FROM karratha135_pdc.navision_backend_records WHERE id=src.id FOR UPDATE;
  IF FOUND THEN own_link:=own.canonical_vehicle_id;
  ELSE
   SELECT count(*),min(v.id::text)::uuid INTO matches,own_link
    FROM karratha135_pdc.vehicles v
    WHERE btrim(v.stock_number)=btrim(coalesce(src.normalized_data->>'batch',src.normalized_data->>'stock',''))
     AND v.deleted_at IS NULL AND v.lifecycle_state::text='active'
     AND EXISTS(SELECT 1 FROM karratha135_pdc.pdc_pilbara_service_operations o
       WHERE o.vehicle_id=v.id AND o.department='135');
   IF matches<>1 THEN own_link:=NULL; END IF;
  END IF;
  -- The PMB canonical_vehicle_id is deliberately never read into the own link.
  INSERT INTO karratha135_pdc.navision_backend_records(
   id,source_record_id,row_hash,normalized_data,raw_evidence,canonical_vehicle_id,
   first_seen_batch_id,last_seen_batch_id,missing_since_batch_id,is_current,version,
   created_at,updated_at,source_system,dealer_code,record_status)
  VALUES(src.id,src.source_record_id,src.row_hash,src.normalized_data,src.raw_evidence,own_link,
   src.first_seen_batch_id,src.last_seen_batch_id,src.missing_since_batch_id,src.is_current,1,
   src.created_at,src.updated_at,src.source_system,src.dealer_code,src.record_status)
  ON CONFLICT(id) DO UPDATE SET
   source_record_id=excluded.source_record_id,row_hash=excluded.row_hash,
   normalized_data=excluded.normalized_data,raw_evidence=excluded.raw_evidence,
   first_seen_batch_id=excluded.first_seen_batch_id,last_seen_batch_id=excluded.last_seen_batch_id,
   missing_since_batch_id=excluded.missing_since_batch_id,is_current=excluded.is_current,
   version=karratha135_pdc.navision_backend_records.version+1,updated_at=excluded.updated_at,
   source_system=excluded.source_system,dealer_code=excluded.dealer_code,
   record_status=excluded.record_status;
  INSERT INTO karratha135_pdc.shared_navision_projection_state_135(
   shared_record_id,shared_version,shared_updated_at,refreshed_at)
  VALUES(src.id,src.version,src.updated_at,clock_timestamp())
  ON CONFLICT(shared_record_id) DO UPDATE SET
   shared_version=excluded.shared_version,shared_updated_at=excluded.shared_updated_at,
   refreshed_at=excluded.refreshed_at;
  copied:=copied+1;
 END LOOP;
 IF copied>0 THEN
  UPDATE karratha135_pdc.navision_backend_revision
   SET revision=revision+1,updated_at=clock_timestamp() WHERE singleton;
 END IF;
 RETURN jsonb_build_object('ok',true,'refreshed',copied);
END;
$function$;
REVOKE ALL ON FUNCTION karratha135_pdc.refresh_shared_navision_135(jsonb) FROM PUBLIC,anon,authenticated;

-- Integration gate: own native preview/apply must refresh inside a nested transaction
-- whose writes roll back on any native failure. Read facades refresh only existing own identities.
-- Only approved own authenticated facades may call this helper. No direct browser facade is exposed.

-- Additive own135 support only; no existing PMB helper/policy is replaced.
-- 747 is a historic identity-bound recovery workflow, not generic retesting.
-- This does not widen any copied 747 vehicle/stock/table constraint.
CREATE FUNCTION karratha135_pdc.qc_retest_receipt_matches_135(
 p_photo jsonb,p_fresh jsonb,p_signoff jsonb,p_vehicle jsonb,p_object jsonb,
 p_bucket text,p_path text)
RETURNS boolean LANGUAGE sql IMMUTABLE
SET search_path=pg_catalog,extensions
AS $function$
 SELECT coalesce(
  p_bucket='karratha135-qc-evidence-staging'
  AND p_photo->>'bucket_id'=p_bucket AND p_object->>'bucket_id'=p_bucket
  AND p_photo->>'storage_path'=p_path AND p_object->>'name'=p_path
  AND p_object->>'owner_id'=p_photo->>'uploader_id'
  AND p_path ~ ('^qc-finalization/'||(p_photo->>'uploader_id')||'/[0-9a-f-]{36}/[^/]{1,180}$')
  AND p_photo->>'vehicle_id'=p_vehicle->>'id'
  AND p_fresh->>'vehicle_id'=p_photo->>'vehicle_id'
  AND p_signoff->>'vehicle_id'=p_photo->>'vehicle_id'
  AND p_fresh->>'cycle_id'=p_photo->>'cycle_id'
  AND p_signoff->>'cycle_id'=p_photo->>'cycle_id'
  AND p_fresh->>'photo_receipt_id'=p_photo->>'photo_receipt_id'
  AND p_signoff->>'photo_receipt_id'=p_photo->>'photo_receipt_id'
  AND p_fresh->>'event_kind'='fresh_photo_accepted'
  AND p_signoff->>'event_kind'='qc_signed_off_to_rft'
  AND p_signoff#>>'{after_state,fresh_photo_receipt_id}'=p_photo->>'photo_receipt_id'
  AND p_photo#>>'{response,photo_receipt_id}'=p_photo->>'photo_receipt_id'
  AND p_photo#>>'{response,cycle_id}'=p_photo->>'cycle_id'
  AND p_photo#>>'{response,vehicle_id}'=p_photo->>'vehicle_id'
  AND p_fresh->>'request_sha256'=p_photo->>'request_sha256'
  AND p_photo->>'sha256' ~ '^[a-f0-9]{64}$'
  AND p_photo->>'request_sha256'=encode(extensions.digest(convert_to(jsonb_build_object(
   'contract','pdc-qc-retest-photo-747','vehicle_id',p_photo->'vehicle_id',
   'expected_vehicle_version',p_photo->'expected_vehicle_version',
   'cycle_id',p_photo->'cycle_id','bucket_id',p_photo->'bucket_id',
   'storage_path',p_photo->'storage_path','content_type',p_photo->'content_type',
   'byte_length',p_photo->'byte_length','original_byte_length',p_photo->'original_byte_length',
   'image_width',p_photo->'image_width','image_height',p_photo->'image_height',
   'sha256',p_photo->'sha256','original_filename',p_photo->'original_filename',
   'idempotency_key',p_photo->'idempotency_key','actor_id',p_photo->'uploader_id')::text,'UTF8'),'sha256'),'hex')
  AND p_vehicle ? 'deleted_at' AND p_vehicle->>'deleted_at' IS NULL
  AND p_vehicle->>'qc_completed_at' IS NOT NULL
  AND p_vehicle->>'rft_transferred_at' IS NOT NULL
  AND p_vehicle->>'current_location' IN('RFT','Collected'),false);
$function$;
REVOKE ALL ON FUNCTION karratha135_pdc.qc_retest_receipt_matches_135(jsonb,jsonb,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION karratha135_pdc.qc_retest_photo_read_allowed_135(p_bucket text,p_path text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,karratha135_pdc
AS $function$
 SELECT p_bucket='karratha135-qc-evidence-staging'
 AND karratha135_pdc.require_active_session_135() IS NOT NULL
 AND karratha135_pdc.current_pdc_user_role() IN('operator','administrator')
 AND EXISTS(
  SELECT 1 FROM karratha135_pdc.pdc_qc_retest_photo_evidence_747 p
  JOIN karratha135_pdc.vehicles v ON v.id=p.vehicle_id
  JOIN karratha135_pdc.pdc_qc_retest_events_747 f
   ON f.vehicle_id=p.vehicle_id AND f.cycle_id=p.cycle_id
    AND f.photo_receipt_id=p.photo_receipt_id AND f.event_kind='fresh_photo_accepted'
  JOIN karratha135_pdc.pdc_qc_retest_events_747 q
   ON q.vehicle_id=p.vehicle_id AND q.cycle_id=p.cycle_id
    AND q.photo_receipt_id=p.photo_receipt_id AND q.event_kind='qc_signed_off_to_rft'
  JOIN storage.objects o ON o.bucket_id=p.bucket_id AND o.name=p.storage_path
  WHERE p.bucket_id=p_bucket AND p.storage_path=p_path
   AND NOT EXISTS(SELECT 1 FROM karratha135_pdc.pdc_qc_retest_events_747 r
    WHERE r.cycle_id=p.cycle_id AND r.vehicle_id=p.vehicle_id AND r.event_kind='rollback')
   AND karratha135_pdc.qc_retest_receipt_matches_135(to_jsonb(p),to_jsonb(f),to_jsonb(q),to_jsonb(v),to_jsonb(o),p_bucket,p_path)
 );
$function$;
REVOKE ALL ON FUNCTION karratha135_pdc.qc_retest_photo_read_allowed_135(text,text) FROM PUBLIC,anon,authenticated,service_role;

-- Integrate before creating the two new own-bucket policies:
-- public.k135_storage_qc_read_allowed must keep its current own session/bucket
-- gate, then require (own native pdc_rft_qc_photo_read_allowed OR the helper
-- above). Both branches query only own receipts and the exact private bucket.

-- Companion to the mechanically copied engine. Candidate only.
-- Adds an own private bucket and two own-bucket-only policies.
-- No existing Storage policy, grant or bucket is modified.
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES('karratha135-qc-evidence-staging','karratha135-qc-evidence-staging',false,NULL,NULL);

CREATE FUNCTION public.k135_storage_qc_upload_allowed(p_bucket text,p_path text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,karratha135_pdc
AS $function$
 SELECT p_bucket='karratha135-qc-evidence-staging'
 AND karratha135_pdc.require_active_session_135() IS NOT NULL
 AND auth.role()='authenticated' AND auth.uid() IS NOT NULL
 AND p_path LIKE ('qc-finalization/'||auth.uid()::text||'/%')
 AND EXISTS(SELECT 1 FROM karratha135_pdc.pdc_user_roles r
   JOIN auth.users u ON u.id=r.auth_user_id
   WHERE r.auth_user_id=auth.uid()
     AND lower(r.email)=lower(btrim(coalesce(auth.jwt()->>'email','')))
     AND lower(u.email)=lower(r.email)
     AND u.deleted_at IS NULL
     AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp())
     AND r.active AND r.account_status='approved'
     AND r.role IN('operator','administrator'));
$function$;
REVOKE ALL ON FUNCTION public.k135_storage_qc_upload_allowed(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.k135_storage_qc_upload_allowed(text,text) TO authenticated;

CREATE FUNCTION public.k135_storage_qc_read_allowed(p_bucket text,p_path text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,karratha135_pdc
AS $function$
 SELECT p_bucket='karratha135-qc-evidence-staging'
 AND karratha135_pdc.require_active_session_135() IS NOT NULL
 AND (karratha135_pdc.pdc_rft_qc_photo_read_allowed(p_bucket,p_path) OR karratha135_pdc.qc_retest_photo_read_allowed_135(p_bucket,p_path));
$function$;
REVOKE ALL ON FUNCTION public.k135_storage_qc_read_allowed(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.k135_storage_qc_read_allowed(text,text) TO authenticated;

CREATE POLICY k135_qc_evidence_upload ON storage.objects
FOR INSERT TO authenticated
WITH CHECK(bucket_id='karratha135-qc-evidence-staging'
 AND public.k135_storage_qc_upload_allowed(bucket_id,name));

CREATE POLICY k135_qc_evidence_read ON storage.objects
FOR SELECT TO authenticated
USING(bucket_id='karratha135-qc-evidence-staging'
 AND public.k135_storage_qc_read_allowed(bucket_id,name));

