('karratha135_navision_upload','preview_profile','p_profile text, p_rows jsonb, p_source_name text, p_source_timestamp timestamp with time zone','c0da397862d00fa14143d5ba5a891c55924fb9c2d4b315a583f47ad7e04cbd60','75c0b3344ede5f3fcca1207ecd1f65891674f5b98f3cfd17aacdfbda1a6ffd26'),
('karratha135_navision_upload','review_complete_snapshot','p_profile text, p_rows jsonb, p_source_name text, p_source_timestamp timestamp with time zone, p_source_hash text, p_preview_hash text, p_expected_revision bigint','c20745577f39de3c340c73ac5a2c4e896c370fd6b6926407d011136f3105a3e0','db53bec754beb86d12432c3b0761a6ea80553a4ceabaa105be4a1f8ec9226278'),
('karratha135_navision_upload','split_profile','p_rows jsonb, p_profile text','ec2f42547c1eb7199d1ee80bb93d7970718a0593a308cef68a7cf4a36f61ba12','166916b320ebd06a579aa0d062baf5fc0ef81d167f20079ee5516de98105734c'),
('karratha135_parts','job_status','j karratha135_parts.jobs','74e130d9d412c1fcbe6c17a052243ebf10203a3364a1d3af7f56ebe6b94f58e6','9a4ee01dc947e4a5e651c0058cf98aa96b00e546b7623c7b09f5706c1b365232'),
('karratha135_parts','planner_search_identity_20260917','p_vehicle_id uuid','00eed52510a4dbadb452bbe862d6940dd539ac78bd922d08bed0d8deb07228fa','daeb74a551e30164ba7fadf29f968f20f41cb5aa162c97da3bb6d36148079d7f'),
('karratha135_parts','planner_search_snapshot_20260917','p_snapshot jsonb','487dfed8949dd36e660c3e5976c09981789e70b2c8bab58fcfee842ef437aed3','24ce28ed3a753b1885986f4cde569e52aeb99f018e91083a215a95d48875f12f'),
('karratha135_parts','service_mapping_issue','rows jsonb','fb6a161acc997f731902d004eba1eacafe04678fcd5768396879b088ec53eddd','d7e5ce5b59ca2a86c00582246025313cf56898ba681345859d4cc2939b52e466'),
('karratha135_parts','service_scope','raw jsonb, stock text, ro text','8ecf7624013e7ecf73dcccc65884401e5c0f4c82afd2a8db3acdd78c9d58a3da','63e9b1a7f649588948753e1f15c677673eb480f59e5cf84aa12355f2e7bb0b8e'),
('karratha135_parts','sync_service_jobs','','f176df3648528b35cab4a2c08fca56997f9fa9ee3b32ac5c8b89f8798b24709b','63b434026ba281e9c70efadb0cf72d05b4355e3e1db14680bcd566613dd90f17'),
('karratha135_planner_access','require_vehicle_planner','','2667d6f8018f60a656512bf0f14c2f34eefcd71e27c2c37402912c7f23d1bc50','13b6ac0c1901c2adc088d3caabd0918a349304ff46d04b0248d88a176b14b4f6'),
('karratha135_usage','record_usage','p_batch_id uuid, p_page text, p_clicks integer, p_visit boolean','458af6cee44bae036881f12898a1eda76a501463b9173aeb850f743c6839ded9','02747147a60ab9d1e271f55383b87cfeae7ec0eda3b446383e2efd6d8ac29a9d'),
('karratha135_usage','report_usage','p_days integer','57bfdec3bae104a9503005a3624b1aec0efd4fc6b790574b5dbfd38cbbf9fcad','fc970939a155ad054c4c47a126435f752ce81985ab6330c990e7fd763ee09c48'),
('karratha135_priority','request','p_stock_number text, p_apply boolean, p_plan_hash text, p_idempotency_key uuid','9a2db29ae6c54365d44c4ec4fbb234b6e1911445abcd3ba5cb82d4bb77c5c352','8dc4738a1d1153c411abf7d9ad5ea27cb111b73f28e5b9949a9ca11b0ec5a581'),
('karratha135_priority','reschedule','p_vehicle uuid, p_floor timestamp with time zone','654e149428df0b00d752a54d965fde4e93d25a843758ab1dba20a660340e8c86','7e2566785ad141e8635d78ca420d6eaa2562d48725b786c334e6a3c6223a343b'),
('karratha135_priority','slot','p_booking uuid, p_bay uuid, p_minutes integer, p_floor timestamp with time zone, p_mode text','a2b827b9c3ecd47ba56d45f282de549af7c0fe74aed705fb0065324fa1cda0b7','e057d381fe37a9b62320fd4253a175df65d85f25ab22c600865c1e98d032e5c0'),
('karratha135_priority','state_hash','p_stock text, p_floor timestamp with time zone','b9d67244eb49c435556657390261dd99481e402ec860a77249c228280447ff88','3bef797ced7f5ee1f6ee14a6ddfa1e0940f5acf9b4d89ad11861a1fb7dcf8c65')
), actual AS (
 SELECT n.nspname schema_name,p.proname function_name,pg_get_function_identity_arguments(p.oid) identity_arguments,
  encode(extensions.digest(convert_to(replace(replace(p.prosrc,E'\r\n',E'\n'),E'\r',E'\n'),'UTF8'),'sha256'),'hex') body_sha256,
  encode(extensions.digest(convert_to(btrim(regexp_replace(replace(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'),E'\r',E'\n'),E'[ \t]+(\n|$)',E'\\1','g'),E'\n')||E'\n','UTF8'),'sha256'),'hex') definition_sha256
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname LIKE 'karratha135\_%' ESCAPE '\' AND p.prokind='f'
), checked AS (
 SELECT e.schema_name,e.function_name,e.identity_arguments,a.function_name IS NOT NULL present,
  a.body_sha256=e.body_sha256 body_matches,a.definition_sha256=e.definition_sha256 definition_matches
 FROM expected e LEFT JOIN actual a USING(schema_name,function_name,identity_arguments)
)
SELECT jsonb_build_object('expected_methods',count(*),'present_methods',count(*) FILTER(WHERE present),
 'exact_body_count',count(*) FILTER(WHERE body_matches),'exact_definition_count',count(*) FILTER(WHERE definition_matches),
 'ok',bool_and(present AND body_matches AND definition_matches),
 'mismatches',coalesce(jsonb_agg(jsonb_build_object('schema',schema_name,'name',function_name,'arguments',identity_arguments,
  'present',present,'body_matches',coalesce(body_matches,false),'definition_matches',coalesce(definition_matches,false)))
  FILTER(WHERE NOT coalesce(present AND body_matches AND definition_matches,false)),'[]'::jsonb)
) AS installed_native_definition_proof FROM checked;

-- Last SQL before orchestrator rollback/commit. No protected mutation survives.
SET LOCAL search_path = public,extensions;
DO $fingerprint$
DECLARE p record; found_hash text;found_count bigint;role_hash text;
 own_clock jsonb;old_clock jsonb;old_allocator jsonb;new_allocator jsonb;expected_jobid bigint;row_expression text;
 external_run record;run_allocator jsonb;max_external_growth bigint;
BEGIN
 IF (SELECT count(*) FROM pg_temp.k135_retired_own_api_plan) NOT IN(0,10) OR EXISTS(
  SELECT 1 FROM pg_temp.k135_retired_own_api_plan plan JOIN pg_proc f ON f.oid=plan.object_id JOIN pg_namespace n ON n.oid=f.pronamespace
  LEFT JOIN pg_temp.k135_protected_functions baseline ON baseline.object_id=f.oid
  WHERE baseline.object_id IS NULL OR baseline.original_acl IS NULL
   OR (n.nspname||'.'||f.proname||'('||pg_get_function_identity_arguments(f.oid)||')') NOT IN(
    'public.get_karratha_pdc_context()','public.get_karratha_pdc_snapshot(p_date_from date, p_date_to date)',
    'public.preview_karratha_nuvu_import(p_file_name text, p_file_sha256 text, p_rows jsonb)',
    'public.apply_karratha_nuvu_import(p_preview_id uuid, p_expected_version integer)',
    'public.save_karratha_pdc(p_action text, p_id uuid, p_expected_version integer, p_data jsonb)',
    'karratha_pdc.context()','karratha_pdc.snapshot(p_date_from date, p_date_to date)',
    'karratha_pdc.preview(p_file_name text, p_file_sha256 text, p_rows jsonb)',
    'karratha_pdc.apply_import(p_preview_id uuid, p_expected_version integer)',
    'karratha_pdc.save(p_action text, p_id uuid, p_expected_version integer, p_data jsonb)')
   OR plan.expected_acl IS DISTINCT FROM ARRAY(SELECT acl FROM unnest(baseline.original_acl) acl WHERE split_part(acl::text,'=',1)<>'authenticated')::aclitem[]
 ) THEN RAISE EXCEPTION 'Unreviewed retirement ACL allowance';END IF;
 FOR p IN SELECT * FROM pg_temp.k135_protected_catalog LOOP
  found_hash:=NULL;
  CASE p.kind
   WHEN 'function' THEN
    IF EXISTS(SELECT 1 FROM pg_temp.k135_retired_own_api_plan WHERE object_id=p.object_id) THEN
     IF NOT EXISTS(SELECT 1 FROM pg_proc x JOIN pg_temp.k135_protected_functions b ON b.object_id=x.oid
      JOIN pg_temp.k135_retired_own_api_plan plan ON plan.object_id=x.oid WHERE x.oid=p.object_id
      AND md5(concat_ws('|',pg_get_functiondef(x.oid),x.proowner::text,x.proconfig::text))=b.non_acl_fingerprint
      AND x.proacl IS NOT DISTINCT FROM plan.expected_acl) THEN RAISE EXCEPTION 'Retired own function definition or unexpected ACL changed';END IF;
     found_hash:=p.fingerprint;
    ELSE SELECT md5(concat_ws('|',pg_get_functiondef(x.oid),x.proowner::text,x.proacl::text,x.proconfig::text)) INTO found_hash FROM pg_proc x WHERE x.oid=p.object_id;END IF;
   WHEN 'relation' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_class x WHERE x.oid=p.object_id;
   WHEN 'sequence_definition' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_sequence x WHERE x.seqrelid=p.object_id;
   WHEN 'index' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_index x WHERE x.indexrelid=p.object_id;
   WHEN 'constraint' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_constraint x WHERE x.oid=p.object_id;
   WHEN 'trigger' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_trigger x WHERE x.oid=p.object_id;
   WHEN 'policy' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_policy x WHERE x.oid=p.object_id;
   WHEN 'namespace' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_namespace x WHERE x.oid=p.object_id;
   WHEN 'roles' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_roles x WHERE x.oid=p.object_id;
   WHEN 'type' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_type x WHERE x.oid=p.object_id;
   WHEN 'enum' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_enum x WHERE x.oid=p.object_id;
   WHEN 'rule' THEN SELECT md5(to_jsonb(x)::text||pg_get_ruledef(x.oid,true)) INTO found_hash FROM pg_rewrite x WHERE x.oid=p.object_id;
   WHEN 'publication' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_publication x WHERE x.oid=p.object_id;
   WHEN 'publication_relation' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_publication_rel x WHERE x.oid=p.object_id;
   WHEN 'defaults' THEN SELECT md5(to_jsonb(x)::text) INTO found_hash FROM pg_default_acl x WHERE x.oid=p.object_id;
   ELSE RAISE EXCEPTION 'Unknown fingerprint kind %',p.kind;
  END CASE;
  IF found_hash IS DISTINCT FROM p.fingerprint THEN RAISE EXCEPTION 'Existing protected % object % changed',p.kind,p.object_id; END IF;
 END LOOP;
 -- New realtime membership is allowed only for a new mapped own relation and
 -- only where the original relation already had the exact same publication,
 -- projected columns, row filter and replica identity. Existing rows above
 -- remain byte/digest identical; no PMB publication setting is changed.
 FOR p IN SELECT r.*,n.nspname,c.relname,c.relreplident,c.relrowsecurity FROM pg_publication_rel r
  JOIN pg_class c ON c.oid=r.prrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old WHERE old.kind='publication_relation' AND old.object_id=r.oid) LOOP
  IF p.prrelid IN(SELECT object_id FROM pg_temp.k135_protected_catalog WHERE kind='relation') OR NOT p.relrowsecurity
   OR NOT EXISTS(SELECT 1 FROM pg_temp.k135_own_namespace_map map JOIN pg_temp.k135_publication_source_members source
    ON source.source_schema=map.source_schema AND source.source_name=p.relname AND source.publication_id=p.prpubid
    WHERE map.target_schema=p.nspname AND p.prattrs IS NOT DISTINCT FROM source.attributes
     AND pg_get_expr(p.prqual,p.prrelid) IS NOT DISTINCT FROM source.row_filter AND p.relreplident=source.replica_identity)
  THEN RAISE EXCEPTION 'Unreviewed new realtime publication membership or replica identity';END IF;
 END LOOP;
 FOR p IN SELECT * FROM pg_temp.k135_protected_columns LOOP
  SELECT md5(to_jsonb(a)::text||coalesce(pg_get_expr(d.adbin,d.adrelid),'')) INTO found_hash FROM pg_attribute a
   LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=p.object_id AND a.attnum=p.attribute_number AND NOT a.attisdropped;
  IF found_hash IS DISTINCT FROM p.fingerprint THEN RAISE EXCEPTION 'Existing protected column %/% changed',p.object_id,p.attribute_number; END IF;
 END LOOP;
 SELECT md5(coalesce(string_agg(to_jsonb(m)::text,E'\n' ORDER BY m.roleid,m.member,m.grantor),'')) INTO role_hash FROM pg_auth_members m;
 IF role_hash IS DISTINCT FROM(SELECT fingerprint FROM pg_temp.k135_protected_role_bindings) THEN RAISE EXCEPTION 'Existing role memberships changed'; END IF;
 -- New state objects on an old relation can change its rules even if all old
 -- objects remain intact. Only the reviewed fresh Storage policies are allowed.
 IF EXISTS(SELECT 1 FROM pg_trigger x WHERE x.tgrelid IN(SELECT object_id FROM pg_temp.k135_protected_catalog WHERE kind='relation')
  AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old_object WHERE old_object.kind='trigger' AND old_object.object_id=x.oid)) THEN
  RAISE EXCEPTION 'Fresh trigger added to an existing protected relation';
 END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint x WHERE x.conrelid IN(SELECT object_id FROM pg_temp.k135_protected_catalog WHERE kind='relation')
  AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old_object WHERE old_object.kind='constraint' AND old_object.object_id=x.oid)) THEN
  RAISE EXCEPTION 'Fresh constraint added to an existing protected relation';
 END IF;
 IF EXISTS(SELECT 1 FROM pg_index x WHERE x.indrelid IN(SELECT object_id FROM pg_temp.k135_protected_catalog WHERE kind='relation')
  AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old_object WHERE old_object.kind='index' AND old_object.object_id=x.indexrelid)) THEN
  RAISE EXCEPTION 'Fresh index added to an existing protected relation';
 END IF;
 FOR p IN SELECT x.*,n.nspname,c.relname FROM pg_policy x JOIN pg_class c ON c.oid=x.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE x.polrelid IN(SELECT object_id FROM pg_temp.k135_protected_catalog WHERE kind='relation')
   AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old WHERE old.kind='policy' AND old.object_id=x.oid) LOOP
  IF p.nspname<>'storage' OR p.relname<>'objects' OR p.polname NOT IN('k135_qc_evidence_upload','k135_qc_evidence_read')
   OR NOT p.polpermissive OR p.polroles<>ARRAY[(SELECT oid FROM pg_roles WHERE rolname='authenticated')]::oid[]
   OR (CASE p.polname
    WHEN 'k135_qc_evidence_upload' THEN p.polcmd<>'a' OR p.polqual IS NOT NULL OR
      regexp_replace(replace(coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),'public.',''),'[[:space:]]','','g')<>'((bucket_id=''karratha135-qc-evidence-staging''::text)ANDk135_storage_qc_upload_allowed(bucket_id,name))'
    WHEN 'k135_qc_evidence_read' THEN p.polcmd<>'r' OR p.polwithcheck IS NOT NULL OR
      regexp_replace(replace(coalesce(pg_get_expr(p.polqual,p.polrelid),''),'public.',''),'[[:space:]]','','g')<>'((bucket_id=''karratha135-qc-evidence-staging''::text)ANDk135_storage_qc_read_allowed(bucket_id,name))'
    ELSE true END)
  THEN RAISE EXCEPTION 'Unreviewed fresh policy on existing protected relation'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_default_acl d WHERE(d.defaclnamespace=0 OR d.defaclnamespace IN(SELECT oid FROM pg_temp.k135_protected_schemas))
  AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_protected_catalog old_object WHERE old_object.kind='defaults' AND old_object.object_id=d.oid)) THEN
  RAISE EXCEPTION 'Fresh default privilege added to existing namespace';
 END IF;
 -- The sole shared allocator exception is a single cron.schedule allocation
 -- accompanied by the exact new own clock. Do not run cron.schedule in a
 -- rollback rehearsal: nextval is not transactional and must never be reset.
 IF (SELECT count(*) FROM cron.job WHERE jobname='k135-staging-workshop-clock-cascade')>1 THEN
  RAISE EXCEPTION 'More than one new own clock';
 END IF;
 SELECT to_jsonb(j) INTO own_clock FROM cron.job j WHERE jobname='k135-staging-workshop-clock-cascade';
 IF own_clock IS NOT NULL THEN
  SELECT source_job,allocator_before INTO STRICT old_clock,old_allocator FROM pg_temp.k135_clock_allowance;
  SELECT jsonb_build_object('last_value',s.last_value,'log_cnt',s.log_cnt,'is_called',s.is_called) INTO new_allocator FROM cron.jobid_seq s;
  expected_jobid:=(old_allocator->>'last_value')::bigint+CASE WHEN (old_allocator->>'is_called')::boolean THEN 1 ELSE 0 END;
  IF own_clock->>'schedule'<>'* * * * *' OR own_clock->>'command'<>'SELECT karratha135_pdc.workshop_clock_tick(true,clock_timestamp());'
   OR own_clock->>'jobname'<>'k135-staging-workshop-clock-cascade' OR NOT (own_clock->>'active')::boolean
   OR (own_clock->>'jobid')::bigint<>expected_jobid
   OR (own_clock-'jobid'-'jobname'-'command') IS DISTINCT FROM (old_clock-'jobid'-'jobname'-'command')
   -- log_cnt is PostgreSQL WAL reservation bookkeeping, and one nextval can
   -- reserve its normal 32 future log entries without allocating extra IDs.
   OR (new_allocator-'log_cnt') IS DISTINCT FROM (jsonb_set(jsonb_set(old_allocator,'{last_value}',to_jsonb(expected_jobid)),'{is_called}','true'::jsonb)-'log_cnt')
   OR (new_allocator->>'log_cnt')::bigint NOT BETWEEN 0 AND 32
  THEN RAISE EXCEPTION 'Unreviewed own cron row or shared allocator change'; END IF;
 END IF;
 SELECT * INTO STRICT external_run FROM pg_temp.k135_concurrent_cron_allocator;
 SELECT jsonb_build_object('last_value',s.last_value,'log_cnt',s.log_cnt,'is_called',s.is_called)
  INTO run_allocator FROM cron.runid_seq s;
 IF run_allocator IS DISTINCT FROM external_run.before_state THEN
  max_external_growth:=greatest(1,cardinality(external_run.protected_job_ids))
   * (ceil(extract(epoch FROM (clock_timestamp()-external_run.captured_from))/60)::bigint+2);
  IF (external_run.before_state->>'is_called')::boolean IS NOT TRUE
   OR (run_allocator->>'is_called')::boolean IS NOT TRUE
   OR (run_allocator->>'last_value')::bigint<=(external_run.before_state->>'last_value')::bigint
   OR (run_allocator->>'last_value')::bigint-(external_run.before_state->>'last_value')::bigint>least(max_external_growth,10000)
   OR (run_allocator->>'log_cnt')::bigint NOT BETWEEN 0 AND 32
  THEN RAISE EXCEPTION 'Concurrent cron allocation is not a bounded monotonic run ID advance';END IF;
  UPDATE pg_temp.k135_concurrent_cron_allocator SET after_state=run_allocator,captured_to=clock_timestamp(),
   first_runid=(before_state->>'last_value')::bigint+1,last_runid=(run_allocator->>'last_value')::bigint,
   requires_external_proof=true;
 ELSE
  UPDATE pg_temp.k135_concurrent_cron_allocator SET after_state=run_allocator,captured_to=clock_timestamp();
 END IF;
 FOR p IN SELECT * FROM pg_temp.k135_protected_data ORDER BY schema_name,table_name LOOP
  IF p.schema_name='cron' AND p.table_name='jobid_seq' AND own_clock IS NOT NULL THEN CONTINUE; END IF;
  IF p.schema_name='cron' AND p.table_name='runid_seq' AND EXISTS(SELECT 1 FROM pg_temp.k135_concurrent_cron_allocator WHERE requires_external_proof) THEN CONTINUE; END IF;
  row_expression:=CASE WHEN EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=p.object_id AND c.relkind='S') THEN 'jsonb_build_object(''last_value'',x.last_value,''log_cnt'',x.log_cnt,''is_called'',x.is_called)' ELSE 'to_jsonb(x)' END;
  EXECUTE format('SELECT count(*),md5(coalesce(string_agg(h,'''' ORDER BY h),'''')) FROM(SELECT md5(%s::text) h FROM %I.%I x%s) q',
   row_expression,p.schema_name,p.table_name,p.where_clause) INTO found_count,found_hash;
  IF found_count IS DISTINCT FROM p.row_count OR found_hash IS DISTINCT FROM p.row_hash THEN
   RAISE EXCEPTION 'Existing protected %.% rows/sequence state changed',p.schema_name,p.table_name;
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM storage.buckets WHERE id='karratha135-qc-evidence-staging' AND(name<>id OR public)) THEN
  RAISE EXCEPTION 'New135 bucket is public or mismatched';
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.k135_concurrent_cron_allocator WHERE requires_external_proof) THEN
  RAISE NOTICE 'Protected fingerprint complete except bounded concurrent cron run IDs: external metadata proof REQUIRED';
 ELSE RAISE NOTICE 'All existing schema objects/ACL/policies and digest-only data/sequence fingerprints unchanged'; END IF;
END $fingerprint$;

-- Append after the suffix, before COMMIT/ROLLBACK. No customer values returned.
-- A changed non-MVCC cron run allocator is NOT certified here; root must verify
-- every run ID in a separate read-only snapshot using the evidence below.
SELECT jsonb_build_object('concurrent_cron_allocator',to_jsonb(a),
 'protected_sequence_exceptions',CASE WHEN a.requires_external_proof THEN ARRAY['cron.runid_seq'] ELSE ARRAY[]::text[] END)
 AS protected_boundary_evidence FROM pg_temp.k135_concurrent_cron_allocator a;
